def hashit(arr, size, mod=10 ** 9 + 7):
	if not size:
		return
	(mul, hashh, div) = (256, 0, (1 << 8 * size - 8) % mod)
	C = defaultdict(list)
	for i in range(size):
		hashh = (mul * hashh + arr[i]) % mod
	C[hashh].append(0)
	for i in range(len(arr) - size):
		hashh = (mul * (hashh - arr[i] * div) + arr[i + size]) % mod
		C[hashh].append(i + 1)
	return C

def LIS(arr, n):
	dp = [10 ** 9] * (n + 1)
	for ele in arr:
		dp[bisect_left(dp, ele)] = ele
	return bisect_left(dp, 10 ** 9)

def exponentiation(bas, exp, mod=10 ** 9 + 7):
	t = 1
	while exp > 0:
		if exp % 2 != 0:
			t = t * bas % mod
		bas = bas * bas % mod
		exp //= 2
	return t % mod

def MOD(p, q=1, mod=1000000007):
	expo = 0
	expo = mod - 2
	while expo:
		if expo & 1:
			p = p * q % mod
		q = q * q % mod
		expo >>= 1
	return p
